                input.date(), loaded.note(), loaded.status(), number, loaded.settledDue(), loaded.openedBy(),
                loaded.stated(), loaded.statedDue(), loaded.corrects(), loaded.dueBy(), loaded.deferredUntil(),
                loaded.proofs(), loaded.splitFrom())));
    }

    private static String periodOf(java.util.List<Period> all, Claim claim) {
        return all.stream().filter(p -> p.contains(claim.date())).map(Period::name).findFirst().orElse(null);
    }

    private static String periodOf(java.util.List<Period> all, RedateInput input) {
        return all.stream().filter(p -> p.contains(input.date())).map(Period::name).findFirst().orElse(null);
    }
}
